import type { PGlite } from "@electric-sql/pglite";
import {
  CompiledQuery,
  type DatabaseConnection,
  type Dialect,
  type Driver,
  type Kysely,
  PostgresAdapter,
  PostgresIntrospector,
  PostgresQueryCompiler,
  type QueryResult,
} from "kysely";

/**
 * @file A Kysely dialect over one PGlite instance: Kysely's own Postgres adapter, compiler and
 * introspector, plus a driver that runs compiled queries through `PGlite#query`.
 *
 * Written here rather than taken from npm (2026-09-28): `kysely-pglite-dialect` 1.3.1 declares
 * `@electric-sql/pglite` peer `^0.2 || ^0.3 || ^0.4` (this package pins 0.5.8), is one maintainer, and is
 * ~11 KB of the same few lines; `kysely-pglite` was last published 2024. This file is that driver,
 * sized to what the kernel needs and nothing else.
 *
 * PGlite is ONE connection. The driver hands it out one holder at a time (a transaction holds it
 * from `BEGIN` to `COMMIT`), so a statement from outside can never land inside someone else's
 * transaction. The kernel's turn lock already orders callers; this keeps the dialect correct on its
 * own too.
 */

class PgliteConnection implements DatabaseConnection {
  constructor(private readonly client: PGlite) {}

  async executeQuery<R>(compiled: CompiledQuery): Promise<QueryResult<R>> {
    const result = await this.client.query<R>(compiled.sql, [...compiled.parameters]);
    return {
      rows: result.rows,
      ...(result.affectedRows !== undefined ? { numAffectedRows: BigInt(result.affectedRows) } : {}),
    };
  }

  // eslint-disable-next-line require-yield, sonarjs/generator-without-yield -- the interface requires a generator; PGlite has no cursor API here
  async *streamQuery<R>(): AsyncIterableIterator<QueryResult<R>> {
    throw new Error("streaming queries are not supported on PGlite");
  }
}

class PgliteDriver implements Driver {
  private readonly connection: PgliteConnection;
  private holder: Promise<void> = Promise.resolve();
  private releaseHolder: (() => void) | undefined;

  constructor(private readonly client: PGlite) {
    this.connection = new PgliteConnection(client);
  }

  async init(): Promise<void> {
    await this.client.waitReady;
  }

  async acquireConnection(): Promise<DatabaseConnection> {
    const previous = this.holder;
    let release!: () => void;
    this.holder = new Promise((resolve) => (release = resolve));
    await previous;
    this.releaseHolder = release;
    return this.connection;
  }

  async releaseConnection(): Promise<void> {
    const release = this.releaseHolder;
    this.releaseHolder = undefined;
    release?.();
  }

  async beginTransaction(connection: DatabaseConnection): Promise<void> {
    await connection.executeQuery(CompiledQuery.raw("BEGIN"));
  }

  async commitTransaction(connection: DatabaseConnection): Promise<void> {
    await connection.executeQuery(CompiledQuery.raw("COMMIT"));
  }

  async rollbackTransaction(connection: DatabaseConnection): Promise<void> {
    await connection.executeQuery(CompiledQuery.raw("ROLLBACK"));
  }

  /** The PGlite instance belongs to whoever opened it (the kernel closes it). */
  async destroy(): Promise<void> {}
}

export class PgliteDialect implements Dialect {
  constructor(private readonly client: PGlite) {}

  createAdapter() {
    return new PostgresAdapter();
  }

  createDriver(): Driver {
    return new PgliteDriver(this.client);
  }

  createQueryCompiler() {
    return new PostgresQueryCompiler();
  }

  createIntrospector(db: Kysely<unknown>) {
    return new PostgresIntrospector(db);
  }
}

import { FOREIGN_SCHEMA_SIGNAL, COUNT_MISMATCH_SIGNAL } from "./signals.js";
import { spawn } from "node:child_process";

/**
 * @file The Postgres side of a database transfer, behind a port, plus its P0 adapter.
 *
 * The adapter shells out to `psql` rather than selecting a driver. Historically P0 had no installed
 * Postgres driver, and adding `pg` was a supply-chain decision for later slices (see
 * `ADS-memory/reports/2026-09-27-assistant-db-transfer-plan.md` §3.3). The port is what the copier
 * depends on, so swapping in `pg` later touches only this file.
 *
 * The connection string never reaches `psql`'s argv (visible to `ps`): it is split into libpq's own
 * `PG*` environment variables, and every inherited `PG*` variable is dropped first so a stray
 * `PGPASSWORD` in the server's environment can never apply to a user's database.
 */

/** What may be shown about a destination: never the password. */
export interface TargetDescription {
  readonly host: string;
  readonly port: string;
  readonly database: string;
  readonly user: string;
}

/** `error` is a copier-owned failure code or a fixed safe message; server text is private.
 * `copyTable` names the table a failed COPY was loading. */
export type TargetResult<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly error: string; readonly copyTable?: string };

export interface PostgresTargetPort {
  describe(): TargetDescription;
  /** One statement; rows as tab-separated text cells. */
  query(sql: string): Promise<TargetResult<string[][]>>;
  /** A psql script fed through stdin, chunk by chunk, stopping at the first error. */
  runScript(chunks: Iterable<string>): Promise<TargetResult<null>>;
}

export class InvalidConnectionStringError extends Error {}

interface ParsedConnection {
  readonly description: TargetDescription;
  readonly env: Readonly<Record<string, string>>;
}

function parsePostgresUrl({ raw }: { raw: string }, _options = {}): URL {
  let url: URL;
  try {
    url = new URL(raw.trim());
  } catch {
    throw new InvalidConnectionStringError("the connection string is not a valid postgres:// URL");
  }
  if (url.protocol !== "postgres:" && url.protocol !== "postgresql:") {
    throw new InvalidConnectionStringError("the connection string must start with postgres:// or postgresql://");
  }
  return url;
}

/**
 * Splits a `postgres://` / `postgresql://` URL into libpq environment variables.
 *
 * @throws {InvalidConnectionStringError} With a message that never quotes the string itself.
 */
export function parseConnectionString({ raw }: { raw: string }, { applicationName = "database-transfer" }: { applicationName?: string } = {}): ParsedConnection {
  const url = parsePostgresUrl({ raw });
  const host = url.searchParams.get("host") ?? decodeURIComponent(url.hostname);
  const database = decodeURIComponent(url.pathname.replace(/^\//, ""));
  const user = decodeURIComponent(url.username);
  if (host === "" || database === "" || user === "") {
    throw new InvalidConnectionStringError("the connection string must name a host, a user and a database");
  }
  const port = url.port || "5432";
  const env: Record<string, string> = { PGHOST: host, PGPORT: port, PGDATABASE: database, PGUSER: user, PGCONNECT_TIMEOUT: "5", PGAPPNAME: applicationName };
  if (url.password !== "") env.PGPASSWORD = decodeURIComponent(url.password);
  const sslmode = url.searchParams.get("sslmode");
  if (sslmode !== null) env.PGSSLMODE = sslmode;
  return { description: { host, port, database, user }, env };
}

/** The parent environment without any `PG*` variable. */
function environmentWithout(parent: NodeJS.ProcessEnv): Record<string, string> {
  const env: Record<string, string> = {};
  for (const [key, value] of Object.entries(parent)) {
    if (!key.startsWith("PG") && value !== undefined) env[key] = value;
  }
  return env;
}

/** Classifies copier failure codes; arbitrary psql text never reaches public errors or logs.
 * @complexity O(n) time/space in stderr length. */
/** Only the transfer's own signals pass through; any other psql text stays in the log. */
function publicFailure({ message, countedTable }: { message: string; countedTable: string | undefined }): string {
  if (message === FOREIGN_SCHEMA_SIGNAL) return FOREIGN_SCHEMA_SIGNAL;
  if (message.startsWith(`${COUNT_MISMATCH_SIGNAL} `)) return `${COUNT_MISMATCH_SIGNAL} ${countedTable ?? "[redacted]"}`;
  return "psql request failed";
}
function failureFrom({ stderr }: { stderr: string }, _options = {}): { ok: false; error: string; copyTable?: string } {
  const lines = stderr.split("\n").map((line) => line.trim()).filter((line) => line !== "");
  const line = lines.find((candidate) => /\bERROR:|FATAL:|could not|timeout/i.test(candidate)) ?? lines[0] ?? "psql failed without a message";
  const message = line.replace(/^psql:[^ ]*: /, "").replace(/^ERROR:\s*/, "");
  const countMismatch = new RegExp(`^${COUNT_MISMATCH_SIGNAL} ([A-Za-z_][A-Za-z0-9_]{0,62})$`).exec(message);
  const error = publicFailure({ message, countedTable: countMismatch?.[1] });
  const copyMatch = /\bCOPY ([A-Za-z0-9_."]+), line \d+/.exec(stderr);
  const copyTable = copyMatch ? copyMatch[1]!.replace(/"/g, "") : undefined;
  return copyTable === undefined ? { ok: false, error } : { ok: false, error, copyTable };
}

/** The slice of a spawned `psql` child this adapter drives: its three pipes, `error` and `close`. */
export interface PsqlProcess {
  readonly stdin: NodeJS.WritableStream;
  readonly stdout: NodeJS.ReadableStream;
  readonly stderr: NodeJS.ReadableStream;
  on(event: "error", listener: (error: Error) => void): unknown;
  on(event: "close", listener: (code: number | null) => void): unknown;
}

/** Starts `psql` with the given argv and environment; the default resolves it on the host PATH. */
export type PsqlSpawn = (args: readonly string[], options: { env: Record<string, string> }) => PsqlProcess;

const spawnPsql: PsqlSpawn = (args, { env }) =>
  // eslint-disable-next-line sonarjs/no-os-command-from-path -- Operator-installed psql intentionally resolves through the trusted host PATH; connection input supplies PG fields, never the executable or PATH.
  spawn("psql", args, { env, stdio: ["pipe", "pipe", "pipe"] });

function runPsql(env: Record<string, string>, args: readonly string[], chunks: Iterable<string> | null, launch: PsqlSpawn): Promise<TargetResult<string>> {
  return new Promise((resolve) => {
    const child = launch(["-X", "-q", "-v", "ON_ERROR_STOP=1", ...args], { env });
    let stdout = "";
    let stderr = "";
    child.stdout.setEncoding("utf8").on("data", (data: string) => (stdout += data));
    child.stderr.setEncoding("utf8").on("data", (data: string) => (stderr += data));
    child.on("error", () => resolve({ ok: false, error: "psql could not be started" }));
    child.on("close", (code) => resolve(code === 0 ? { ok: true, value: stdout } : failureFrom({ stderr })));
    child.stdin.on("error", () => undefined);
    void (async () => {
      for (const chunk of chunks ?? []) {
        if (!child.stdin.write(chunk)) await new Promise((drain) => child.stdin.once("drain", drain));
      }
      child.stdin.end();
    })();
  });
}

/**
 * The P0 adapter: every call is one short-lived `psql` process, started through `spawnProcess`
 * (default: `psql` on the host PATH).
 *
 * @throws {InvalidConnectionStringError} When the string cannot be parsed.
 */
export function createPsqlPostgresTarget({ connectionString }: { connectionString: string }, { parentEnv = process.env, applicationName, spawnProcess = spawnPsql }: { parentEnv?: NodeJS.ProcessEnv; applicationName?: string; spawnProcess?: PsqlSpawn } = {}): PostgresTargetPort {
  const parsed = parseConnectionString({ raw: connectionString }, applicationName === undefined ? {} : { applicationName });
  const env = { ...environmentWithout(parentEnv), ...parsed.env };
  return {
    describe: () => parsed.description,
    async query(sql) {
      const result = await runPsql(env, ["-t", "-A", "-F", "\t", "-c", sql], null, spawnProcess);
      if (!result.ok) return result;
      const rows = result.value.split("\n").filter((line) => line !== "").map((line) => line.split("\t"));
      return { ok: true, value: rows };
    },
    async runScript(chunks) {
      const result = await runPsql(env, ["-f", "-"], chunks, spawnProcess);
      return result.ok ? { ok: true, value: null } : result;
    },
  };
}
